SELECT cp.post_id, cp.user_idx, u.nickname, cp.title, cp.content, cp.post_status, cp.view_count, cp.like_count, cp.comment_count, cp.report_count, cp.created_at, cp.post_type, cp.region, cp.tip_category, (SELECT image_url FROM COMMUNITY_POST_IMAGE WHERE post_id = cp.post_id ORDER BY sort_order LIMIT 1) AS thumb_url, u.account_status FROM COMMUNITY_POST cp LEFT JOIN USERS u ON cp.user_idx = u.user_idx WHERE cp.post_status IN ('ACTIVE', 'BLOCKED')
AND cp.post_id NOT IN #{id}
ORDER BY cp.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

